package com.shazwan.idash.a1lab;
import android.app.*;import android.content.*;import android.media.*;import android.media.session.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.util.*;import android.media.session.MediaController;
/** Callback-driven MediaSession bridge; notification contents and artwork are never read. */
final class ControlMedia {
 final LauncherActivity a;final QuickControls q;final MediaSessionManager manager;final ComponentName listener;final Handler main=new Handler(Looper.getMainLooper());
 AlertDialog prompt;MediaController controller;boolean active,listening,registered,accessFailed;TextView title,artist,status;View previous,play,next;ControlGlyph playGlyph;
 final MediaSessionManager.OnActiveSessionsChangedListener changed=sessions->select(sessions);
 final MediaController.Callback callback=new MediaController.Callback(){public void onMetadataChanged(MediaMetadata m){if(active)render();}public void onPlaybackStateChanged(PlaybackState s){if(active)render();}public void onSessionDestroyed(){if(active){bind(null);render();}}};
 final BroadcastReceiver access=new BroadcastReceiver(){public void onReceive(Context c,Intent i){reload();}};
 ControlMedia(LauncherActivity a,QuickControls q){this.a=a;this.q=q;manager=(MediaSessionManager)a.getSystemService(Context.MEDIA_SESSION_SERVICE);listener=new ComponentName(a,MediaAccessService.class);}
 boolean granted(){try{NotificationManager n=(NotificationManager)a.getSystemService(Context.NOTIFICATION_SERVICE);return Build.VERSION.SDK_INT>=27&&n!=null&&n.isNotificationListenerAccessGranted(listener);}catch(SecurityException e){return false;}}
 @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag") void resume(){if(active)return;active=true;IntentFilter f=new IntentFilter(MediaAccessService.CHANGED);if(Build.VERSION.SDK_INT>=33)a.registerReceiver(access,f,Context.RECEIVER_NOT_EXPORTED);else a.registerReceiver(access,f);registered=true;reload();}
 void pause(){if(prompt!=null){prompt.dismiss();prompt=null;}active=false;if(listening){try{manager.removeOnActiveSessionsChangedListener(changed);}catch(RuntimeException ignored){}listening=false;}bind(null);if(registered){registered=false;a.unregisterReceiver(access);}}
 void reload(){if(!active)return;if(manager==null||!granted()){if(listening){try{manager.removeOnActiveSessionsChangedListener(changed);}catch(RuntimeException ignored){}listening=false;}bind(null);render();return;}try{accessFailed=false;if(!listening){manager.addOnActiveSessionsChangedListener(changed,listener,main);listening=true;}select(manager.getActiveSessions(listener));}catch(SecurityException denied){accessFailed=true;bind(null);accessNeeded();}}
 void select(List<MediaController> sessions){if(!active)return;MediaController best=null;int score=-1;if(sessions!=null)for(MediaController c:sessions){try{PlaybackState s=c.getPlaybackState();int rank=s==null?0:s.getState()==PlaybackState.STATE_PLAYING?3:s.getState()==PlaybackState.STATE_PAUSED?2:1;if(rank>score){best=c;score=rank;}}catch(RuntimeException ignored){}}bind(best);render();}
 void bind(MediaController selected){if(controller!=null){try{controller.unregisterCallback(callback);}catch(RuntimeException ignored){}}controller=selected;if(controller!=null&&active)try{controller.registerCallback(callback,main);}catch(RuntimeException ignored){controller=null;}}
 static boolean supports(long actions,long action){return (actions&action)!=0;}
 void button(View view,boolean enabled,String description){view.setEnabled(enabled);view.setAlpha(enabled?1:IosStyle.CC_DISABLED_ALPHA);view.setContentDescription(description);}
 void accessNeeded(){title.setText(accessFailed?"Media access unavailable":"Media access needed");artist.setText("Tap card to review access");playGlyph.type=7;playGlyph.invalidate();status.setText("Notification Listener Access");button(previous,false,"Previous · access required");button(play,false,"Play · access required");button(next,false,"Next · access required");}
 void render(){if(title==null)return;if(manager==null){title.setText("Media unavailable");artist.setText("MediaSession service unavailable");status.setText("Unsupported on this device");button(previous,false,"Previous unavailable");button(play,false,"Play unavailable");button(next,false,"Next unavailable");return;}if(!granted()){accessNeeded();return;}try{PlaybackState s=controller==null?null:controller.getPlaybackState();MediaMetadata metadata=controller==null?null:controller.getMetadata();int state=s==null?PlaybackState.STATE_NONE:s.getState();boolean playing=state==PlaybackState.STATE_PLAYING;String name=metadata==null?null:metadata.getString(MediaMetadata.METADATA_KEY_TITLE),by=metadata==null?null:metadata.getString(MediaMetadata.METADATA_KEY_ARTIST);
 title.setText(name==null||name.trim().isEmpty()?(controller==null?"Not Playing":"Untitled media"):name);artist.setText(by==null||by.trim().isEmpty()?(controller==null?"No active media session":"Artist unavailable"):by);String app="";if(controller!=null){try{app=a.getPackageManager().getApplicationLabel(a.getPackageManager().getApplicationInfo(controller.getPackageName(),0)).toString();}catch(Exception ignored){app=controller.getPackageName();}}status.setText((playing?"Playing":state==PlaybackState.STATE_PAUSED?"Paused":state==PlaybackState.STATE_BUFFERING?"Buffering":"Not Playing")+(app.isEmpty()?"":" · "+app));
 long actions=s==null?0:s.getActions();button(previous,supports(actions,PlaybackState.ACTION_SKIP_TO_PREVIOUS),"Previous");button(next,supports(actions,PlaybackState.ACTION_SKIP_TO_NEXT),"Next");button(play,supports(actions,PlaybackState.ACTION_PLAY_PAUSE)||supports(actions,playing?PlaybackState.ACTION_PAUSE:PlaybackState.ACTION_PLAY),playing?"Pause":"Play");((TextView)((android.view.ViewGroup)play).getChildAt(1)).setText(playing?"Pause":"Play");playGlyph.type=playing?15:7;playGlyph.invalidate();
 }catch(RuntimeException ended){bind(null);title.setText("Session unavailable");artist.setText("Open your media app");status.setText("Waiting for session update");button(previous,false,"Previous unavailable");button(play,false,"Play unavailable");button(next,false,"Next unavailable");}}
 void action(int action){if(controller==null||!granted()){reload();return;}try{PlaybackState state=controller.getPlaybackState();long actions=state==null?0:state.getActions();MediaController.TransportControls transport=controller.getTransportControls();if(action==6&&supports(actions,PlaybackState.ACTION_SKIP_TO_PREVIOUS))transport.skipToPrevious();else if(action==8&&supports(actions,PlaybackState.ACTION_SKIP_TO_NEXT))transport.skipToNext();else if(action==7){boolean playing=state!=null&&state.getState()==PlaybackState.STATE_PLAYING;if(supports(actions,playing?PlaybackState.ACTION_PAUSE:PlaybackState.ACTION_PLAY)){if(playing)transport.pause();else transport.play();}else if(supports(actions,PlaybackState.ACTION_PLAY_PAUSE)){controller.dispatchMediaButtonEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_DOWN,android.view.KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE));controller.dispatchMediaButtonEvent(new android.view.KeyEvent(android.view.KeyEvent.ACTION_UP,android.view.KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE));}}}catch(RuntimeException ended){reload();}}
 void explain(){if(manager==null){Toast.makeText(a,"MediaSession service unavailable",Toast.LENGTH_SHORT).show();return;}if(granted()&&!accessFailed){reload();return;}prompt=new AlertDialog.Builder(a).setTitle("Allow media controls?").setMessage("Android requires Notification Listener Access to discover other apps' active MediaSessions. This access is broad: Android can expose notifications to an enabled listener. iDash does not read or store notification contents or artwork; it uses media metadata and transport controls only. Grant access only if you are comfortable with this capability.").setNegativeButton("Cancel",null).setPositiveButton("Open access settings",(d,w)->a.openSettings(Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS)).show();}
}
